#!/usr/bin/env node
// Generated by theorem-harness-package from theorem-harness-core. Do not edit:
// `scripts/check-harness-package.sh` reports any difference as drift.
//
// The only host hook. Usage: theorem-hook.mjs <claude_code|codex> < payload
//
// It decides nothing. Every delivery goes to native `harness_host_event`,
// which normalizes it through the versioned mapping and records it in the
// session's run log. Context events also compile the capability packet with
// `prepare_context` and record its receipts with `write_receipt`; session
// start asks `session_code_context` for the repository's code context. The
// host contributes only facts it alone can see: which capability manifests
// exist in cwd and the checkout's git identity.
//
// A failed step never breaks the host session, and it is never silent: the
// model sees one degraded line naming the step and the reason.

import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";

import { callTool } from "../generated/native-client.mjs";

const ROUTES = JSON.parse(readFileSync(new URL("../../tool-routes.json", import.meta.url), "utf8"));
const host = process.argv[2] ?? "";
const binding = ROUTES.hosts[host];

const raw = await readStdin();
let payload = {};
try {
  payload = raw.trim() ? JSON.parse(raw) : {};
} catch {
  payload = {};
}
const eventName = String(payload.hook_event_name ?? payload.hookEventName ?? "");
const sessionId = String(payload.session_id ?? "");
const cwd = String(payload.cwd ?? process.env.CLAUDE_PROJECT_DIR ?? process.cwd());
const sections = [];
const degraded = [];

if (!binding) {
  degraded.push(`binding: unknown host ${JSON.stringify(host)}`);
} else {
  const recorded = await callTool("harness_host_event", {
    host,
    payload,
    delivery_id: deliveryId(),
    mapping_version: ROUTES.mapping_version,
  });
  note("harness_host_event", recorded);

  if (binding.context_events.includes(eventName)) {
    const presentManifests = ROUTES.capability_manifests.filter((path) => existsSync(join(cwd, path)));
    const prepared = await callTool("prepare_context", { payload, present_manifests: presentManifests });
    if (note("prepare_context", prepared)) {
      const markdown = String(prepared.content.markdown ?? "");
      if (markdown) sections.push(markdown);
      const receipts = prepared.content.packet?.receipt_events ?? [];
      if (receipts.length && sessionId) {
        note("write_receipt", await callTool("write_receipt", { host, session_id: sessionId, event: receipts }));
      }
    }
  }

  if (binding.code_context_events.includes(eventName) && !codeContextManaged()) {
    const repository = gitRepository();
    if (repository) {
      const context = await callTool("session_code_context", {
        ...repository,
        session_id: sessionId,
        prompt: process.env.THEOREM_CONTEXT_TASK ?? "",
        budget_tokens: Number.parseInt(process.env.THEOREM_CONTEXT_BUDGET_TOKENS ?? "", 10) || undefined,
      });
      if (note("session_code_context", context)) {
        if (context.content.status === "current") {
          if (context.content.markdown) sections.push(String(context.content.markdown));
        } else {
          const state = context.content.operation?.state ?? context.content.status;
          sections.push(`Code graph for ${repository.repo_url}@${repository.sha.slice(0, 12)} is ${state}; its context is not in this session yet.`);
        }
      }
    }
  }
}

if (degraded.length) {
  sections.push(`Theorems Harness degraded: ${degraded.join("; ")}`);
}
const additionalContext = sections.join("\n\n");
const response = { continue: true, suppressOutput: true };
if (additionalContext && binding?.additional_context_events.includes(eventName)) {
  response.hookSpecificOutput = { hookEventName: eventName, additionalContext };
} else if (degraded.length) {
  process.stderr.write(`${sections.at(-1)}\n`);
}
process.stdout.write(`${JSON.stringify(response)}\n`);

function note(step, answer) {
  if (!answer.ok) degraded.push(`${step} ${answer.reason}`);
  return answer.ok;
}

// A host that gives an event no durable id gets one derived from the
// delivery itself, which a retry reproduces: the payload bytes and the
// transcript length at the moment the hook fired.
function deliveryId() {
  let transcript = 0;
  try {
    transcript = payload.transcript_path ? statSync(payload.transcript_path).size : 0;
  } catch {
    transcript = 0;
  }
  return createHash("sha256").update(`${host}\n${raw}\n${transcript}`).digest("hex");
}

function codeContextManaged() {
  const owner = String(process.env.THEOREM_CODE_CONTEXT_OWNER ?? process.env.THEOREM_CODE_CONTEXT_MANAGED ?? "").trim().toLowerCase();
  return ["1", "true", "yes", "installed", "theorem"].includes(owner);
}

function gitRepository() {
  const git = (dir, ...args) =>
    execFileSync("git", ["-C", dir, ...args], { encoding: "utf8", timeout: 1500, stdio: ["ignore", "pipe", "ignore"] }).trim();
  try {
    // The origin URL is the repository's identity; a checkout's directory
    // name is not unique, and native keys the ingest operation by it.
    const root = git(cwd, "rev-parse", "--show-toplevel");
    return { repo_url: git(root, "remote", "get-url", "origin"), sha: git(root, "rev-parse", "HEAD") };
  } catch {
    // Not a git checkout with an origin: there is no repository to describe.
    return null;
  }
}

async function readStdin() {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(Buffer.from(chunk));
  return Buffer.concat(chunks).toString("utf8");
}
